<template><el-form ref="refForm" :model="model" label-position="top" :rules="rules" :disabled="disabled"><div class="zj-grid"><el-form-item label="项目名称" prop="projectName"><el-input v-model="model.projectName" maxlength="255"/></el-form-item><el-form-item label="所属合同" prop="contractId"><el-select v-model="model.contractId" filterable remote :remote-method="findContracts" :loading="searching" placeholder="输入合同名称或编号搜索" @visible-change="v=>v&&findContracts('')"><el-option v-for="c in contracts" :key="c.id" :value="c.id" :label="`${c.contractName} · ${c.contractNo||'未填写编号'}`"/></el-select></el-form-item><el-form-item label="委托 / 建设单位"><el-input v-model="model.clientName" maxlength="255"/></el-form-item><el-form-item label="项目地址"><el-input v-model="model.siteAddress" maxlength="500"/></el-form-item><el-form-item label="联系人"><el-input v-model="model.contactName" maxlength="100"/></el-form-item><el-form-item label="联系电话"><el-input v-model="model.contactPhone" maxlength="50"/></el-form-item><el-form-item label="项目负责人"><el-select v-model="model.leaderUserId" clearable filterable remote :remote-method="findUsers" @visible-change="v=>v&&findUsers('')" placeholder="搜索系统用户"><el-option v-for="u in users" :key="u.id" :label="u.name+' ('+(u.username||u.id)+')'" :value="u.id"/></el-select></el-form-item><el-form-item label="技术负责人"><el-select v-model="model.technicalUserId" clearable filterable remote :remote-method="findUsers" @visible-change="v=>v&&findUsers('')" placeholder="搜索系统用户"><el-option v-for="u in users" :key="u.id" :label="u.name+' ('+(u.username||u.id)+')'" :value="u.id"/></el-select></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="model.startDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="model.endDate" value-format="YYYY-MM-DD"/></el-form-item></div></el-form></template>
<script setup>
import {projectContracts,projectUsers} from '@/api/workProject';
const model=defineModel({type:Object,required:true});const props=defineProps({projectType:String,disabled:Boolean,legacy:Boolean});const refForm=ref(),contracts=ref([]),users=ref([]),searching=ref(false);let contractSequence=0,userSequence=0;
const rules={projectName:[{required:true,message:'请填写项目名称',trigger:'blur'}],contractId:[{validator:(_r,v,cb)=>!v&&!props.legacy?cb(new Error('请选择所属合同')):cb(),trigger:'change'}]};
watch(()=>model.value, v=>{contracts.value=v.contractId?[{id:v.contractId,contractName:v.contractName||'已关联合同',contractNo:v.contractNumber}]:[];users.value=[...(v.leaderUserId?[{id:v.leaderUserId,name:v.leaderName||'已选用户'}]:[]),...(v.technicalUserId?[{id:v.technicalUserId,name:v.technicalName||'已选用户'}]:[])];},{immediate:true});
async function findContracts(name){if(props.disabled)return;const n=++contractSequence;searching.value=true;try{const r=await projectContracts({projectType:props.projectType,name,pageSize:20,pageNum:1});if(n===contractSequence)contracts.value=r.rows;}finally{if(n===contractSequence)searching.value=false;}}
async function findUsers(name){if(props.disabled)return;const n=++userSequence;const r=await projectUsers({name,pageSize:20,pageNum:1});if(n===userSequence)users.value=r.rows;}
defineExpose({validate:()=>refForm.value.validate()});
</script>